### Animate a point on a map

Source: https://github.com/maplibre/maplibre-gl-js/blob/main/test/examples/animate-a-point.html

Uses a GeoJSON source and a circle layer, updating the source data within an animation loop.

```css
body { margin: 0; padding: 0; } html, body, #map { height: 100%; }
```

```javascript
import * as maplibregl from '../../dist/maplibre-gl-dev.mjs'; const map = new maplibregl.Map({ container: 'map', style: 'https://demotiles.maplibre.org/style.json', center: [0, 0], zoom: 2 }); const radius = 20; function pointOnCircle(angle) { return { 'type': 'Point', 'coordinates': [Math.cos(angle) * radius, Math.sin(angle) * radius] }; } map.on('load', () => { // Add a source and layer displaying a point which will be animated in a circle. map.addSource('point', { 'type': 'geojson', 'data': pointOnCircle(0) }); map.addLayer({ 'id': 'point', 'source': 'point', 'type': 'circle', 'paint': { 'circle-radius': 10, 'circle-color': '#007cbf' } }); function animateMarker(timestamp) { // Update the data to a new position based on the animation timestamp. The // divisor in the expression `timestamp / 1000` controls the animation speed. map.getSource('point').setData(pointOnCircle(timestamp / 1000)); // Request the next frame of the animation. requestAnimationFrame(animateMarker); } // Start the animation. animateMarker(0); });
```

--------------------------------

### Display HTML Clusters with Custom Properties

Source: https://github.com/maplibre/maplibre-gl-js/blob/main/test/examples/display-html-clusters-with-custom-properties.html

This script initializes a map, adds a clustered GeoJSON source with custom magnitude properties, and uses a custom function to generate SVG donut charts for cluster markers.

```css
body { margin: 0; padding: 0; } html, body, #map { height: 100%; }
```

```javascript
import * as maplibregl from '../../dist/maplibre-gl-dev.mjs'; const map = new maplibregl.Map({ container: 'map', zoom: 0.3, center: [0, 20], style: 'https://demotiles.maplibre.org/style.json' }); map.addControl(new maplibregl.NavigationControl()); // filters for classifying earthquakes into five categories based on magnitude const mag1 = ['<', ['get', 'mag'], 2]; const mag2 = ['all', ['>=', ['get', 'mag'], 2], ['<', ['get', 'mag'], 3]]; const mag3 = ['all', ['>=', ['get', 'mag'], 3], ['<', ['get', 'mag'], 4]]; const mag4 = ['all', ['>=', ['get', 'mag'], 4], ['<', ['get', 'mag'], 5]]; const mag5 = ['>=', ['get', 'mag'], 5]; // colors to use for the categories const colors = ['#fed976', '#feb24c', '#fd8d3c', '#fc4e2a', '#e31a1c']; map.on('load', () => { // add a clustered GeoJSON source for a sample set of earthquakes map.addSource('earthquakes', { 'type': 'geojson', 'data': 'https://maplibre.org/maplibre-gl-js/docs/assets/earthquakes.geojson', 'cluster': true, 'clusterRadius': 80, 'clusterProperties': { // keep separate counts for each magnitude category in a cluster 'mag1': ['+', ['case', mag1, 1, 0]], 'mag2': ['+', ['case', mag2, 1, 0]], 'mag3': ['+', ['case', mag3, 1, 0]], 'mag4': ['+', ['case', mag4, 1, 0]], 'mag5': ['+', ['case', mag5, 1, 0]] } }); // circle and symbol layers for rendering individual earthquakes (unclustered points) map.addLayer({ 'id': 'earthquake_circle', 'type': 'circle', 'source': 'earthquakes', 'filter': ['!=', 'cluster', true], 'paint': { 'circle-color': [ 'case', mag1, colors[0], mag2, colors[1], mag3, colors[2], mag4, colors[3], colors[4] ], 'circle-opacity': 0.6, 'circle-radius': 12 } }); map.addLayer({ 'id': 'earthquake_label', 'type': 'symbol', 'source': 'earthquakes', 'filter': ['!=', 'cluster', true], 'layout': { 'text-field': [ 'number-format', ['get', 'mag'], {'min-fraction-digits': 1, 'max-fraction-digits': 1} ], 'text-font': ['Open Sans Semibold', 'Arial Unicode MS Bold'], 'text-size': 10 }, 'paint': { 'text-color': [ 'case', ['<', ['get', 'mag'], 3], 'black', 'white' ] } }); // objects for caching and keeping track of HTML marker objects (for performance) const markers = {}; let markersOnScreen = {}; function updateMarkers() { const newMarkers = {}; const features = map.querySourceFeatures('earthquakes'); // for every cluster on the screen, create an HTML marker for it (if we didn't yet), // and add it to the map if it's not there already for (let i = 0; i < features.length; i++) { const coords = features[i].geometry.coordinates; const props = features[i].properties; if (!props.cluster) continue; const id = props.cluster_id; let marker = markers[id]; if (!marker) { const el = createDonutChart(props); marker = markers[id] = new maplibregl.Marker({ element: el }).setLngLat(coords); } newMarkers[id] = marker; if (!markersOnScreen[id]) marker.addTo(map); } // for every marker we've added previously, remove those that are no longer visible for (id in markersOnScreen) { if (!newMarkers[id]) markersOnScreen[id].remove(); } markersOnScreen = newMarkers; } // after the GeoJSON data is loaded, update markers on the screen and do so on every map move/moveend map.on('data', (e) => { if (e.sourceId !== 'earthquakes' || !e.isSourceLoaded) return; map.on('move', updateMarkers); map.on('moveend', updateMarkers); updateMarkers(); }); }); // code for creating an SVG donut chart from feature properties function createDonutChart(props) { const offsets = []; const counts = [ props.mag1, props.mag2, props.mag3, props.mag4, props.mag5 ]; let total = 0; for (let i = 0; i < counts.length; i++) { offsets.push(total); total += counts[i]; } const fontSize = total >= 1000 ? 22 : total >= 100 ? 20 : total >= 10 ? 18 : 16; const r = total >= 1000 ? 50 : total >= 100 ? 32 : total >= 10 ? 24 : 18; const r0 = Math.round(r * 0.6); const w = r * 2; let html = `<div><svg width="${ w }" height="${ w }" viewbox="0 0 ${ w } ${ w }" text-anchor="middle" style="font: ${ fontSize }px sans-serif; display: block">`; for (i = 0; i < counts.length; i++) { html += donutSegment( offsets[i] / total, (offsets[i] + counts[i]) / total, r, r0, colors[i] ); } html += `<circle cx="${ r }" cy="${ r }" r="${ r0 }" fill="white" /><text dominant-baseline="central" transform="translate(${ r }, ${ r })">${ total.toLocaleString() }</text></svg></div>`; const el = document.createElement('div'); el.innerHTML = html; return el.firstChild; } function donutSegment(start, end, r, r0, color) { if (end - start === 1) end -= 0.00001; const a0 = 2 * Math.PI * (start - 0.25); const a1 = 2 * Math.PI * (end - 0.25); const x0 = Math.cos(a0), y0 = Math.sin(a0); const x1 = Math.cos(a1), y1 = Math.sin(a1); const largeArc = end - start > 0.5 ? 1 : 0; return [ '<path d="M', r + r0 * x0, r + r0 * 
```

--------------------------------

### Initialize Map and Add Clustered GeoJSON Source

Source: https://github.com/maplibre/maplibre-gl-js/blob/main/test/examples/create-and-style-clusters.html

Sets up the map instance and adds a GeoJSON source with clustering enabled, specifying radius and zoom constraints.

```javascript
import * as maplibregl from '../../dist/maplibre-gl-dev.mjs'; const map = new maplibregl.Map({ container: 'map', style: 'https://demotiles.maplibre.org/style.json', center: [-103.59179687498357, 40.66995747013945], zoom: 3, fadeDuration: 0 // this is in order for the text and circles to move "as-one" }); map.on('load', () => { // Add a new source from our GeoJSON data and // set the 'cluster' option to true. GL-JS will // add the point_count property to your source data. map.addSource('earthquakes', { type: 'geojson', // Point to GeoJSON data. This example visualizes all M1.0+ earthquakes // from 12/22/15 to 1/21/16 as logged by USGS' Earthquake hazards program. data: 'https://maplibre.org/maplibre-gl-js/docs/assets/earthquakes.geojson', cluster: true, clusterMaxZoom: 14, // Max zoom to cluster points on clusterRadius: 50 // Radius of each cluster when clustering points (defaults to 50) });
```

--------------------------------

### Filter map layers with global state

Source: https://github.com/maplibre/maplibre-gl-js/blob/main/test/examples/filter-layer-symbols-using-global-state.html

Initializes a map with a GeoJSON source and applies a filter to layers that reacts to changes in the global state property 'type'.

```javascript
import * as maplibregl from '../../dist/maplibre-gl-dev.mjs'; const map = new maplibregl.Map({ container: 'map', style: 'https://demotiles.maplibre.org/style.json', center: [9.0679, 45.8822], zoom: 9 }); map.on('load', () => { map.addSource('railways_and_lifts', { type: 'geojson', data: 'https://maplibre.org/maplibre-gl-js/docs/assets/funicolares-and-funivias-como.json' }); map.addLayer({ id: 'railways_and_lifts_labels', type: 'symbol', source: 'railways_and_lifts', layout: { 'text-field': '{name}', 'text-font': ['Open Sans Semibold'], 'text-offset': [0, 1], 'text-anchor': 'top' }, paint: { 'text-color': '#000000', 'text-halo-color': '#ffffff', 'text-halo-width': 2 }, filter: [ 'case', ['==', ['to-string', ['global-state', 'type']], ''], true, ['==', ['get', 'type'], ['global-state', 'type']] ] }); map.addLayer({ type: 'circle', id: 'railways_and_lifts_points', source: 'railways_and_lifts', paint: { 'circle-radius': 5, 'circle-color': '#000000', }, filter: [ 'case', ['==', ['to-string', ['global-state', 'type']], ''], true, ['==', ['get', 'type'], ['global-state', 'type']] ] }); const select = document.querySelector('select[name="type"]'); map.setGlobalStateProperty('type', select.value); select.addEventListener('change', (e) => { const value = e.target.value; map.setGlobalStateProperty('type', value); }); });
```

--------------------------------

### CircleStyleLayer — Transition and Feature-State capabilities

Source: https://github.com/maplibre/maplibre-gl-js/blob/main/src/style/style_layer/circle_style_layer.ts

The class shows Transitionable/Transitioning for paint property transitions and the queryIntersectsFeature method evaluates circle-radius and circle-stroke-width with featureState, enabling feature-state-driven styling.

```typescript
export class CircleStyleLayer extends StyleLayer {
    _unevaluatedLayout: Layout<CircleLayoutProps>;
