function toCollection(quakes: Quake[]) {
  return {
    type: "FeatureCollection" as const,
    features: quakes.map((quake) => ({
      type: "Feature" as const,
      id: quake.id,
      properties: {
        id: quake.id,
        mag: quake.mag ?? -1,
        depth: quake.depth ?? -1,
        place: quake.place,
        time: quake.time,
      },
      geometry: {
        type: "Point" as const,
        coordinates: [quake.lon, quake.lat],
      },
    })),
  };
}

