const version = await fetch("http://127.0.0.1:9333/json/version").then(r => r.json());
const browserWs = version.webSocketDebuggerUrl;
const browser = new WebSocket(browserWs);
await new Promise((res, rej) => { browser.onopen = res; browser.onerror = rej; });

let id = 0;
const pending = new Map();
const events = [];
browser.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
  } else events.push(msg);
};
function send(method, params, sessionId) {
  const msg = { id: ++id, method, params };
  if (sessionId) msg.sessionId = sessionId;
  browser.send(JSON.stringify(msg));
  return new Promise((resolve, reject) => pending.set(msg.id, { resolve, reject }));
}

const { targetId } = await send("Target.createTarget", { url: "about:blank" });
const { sessionId } = await send("Target.attachToTarget", { targetId, flatten: true });
await send("Page.enable", {}, sessionId);
await send("Runtime.enable", {}, sessionId);
await send("Emulation.setDeviceMetricsOverride", {
  width: 1440, height: 900, deviceScaleFactor: 1, mobile: false
}, sessionId);
const nav = send("Page.navigate", { url: "http://127.0.0.1:9302/" }, sessionId);
await nav;

const deadline = Date.now() + 25000;
let html = "";
while (Date.now() < deadline) {
  const { result } = await send("Runtime.evaluate", {
    expression: `({
      title: document.title,
      h1: document.querySelector('h1')?.textContent ?? null,
      count: document.body.innerText.slice(0, 500),
      hasMap: !!document.querySelector('.maplibregl-canvas, .map-root canvas, canvas'),
      ready: document.body.innerText.includes('USGS') || document.body.innerText.includes('events')
    })`,
    returnByValue: true
  }, sessionId);
  html = result.value;
  if (html.h1 === "Cursor Grok 4.6" && html.ready) break;
  await new Promise(r => setTimeout(r, 500));
}
console.log(JSON.stringify(html, null, 2));

const shot = await send("Page.captureScreenshot", { format: "png" }, sessionId);
const fs = await import("node:fs");
fs.writeFileSync("/tmp/earthquake-explorer.png", Buffer.from(shot.data, "base64"));
console.log("screenshot", fs.statSync("/tmp/earthquake-explorer.png").size);
browser.close();
