:root {
  --bg: oklch(0.105 0 0);
  --surface: oklch(0.155 0.02 270);
  --surface-2: oklch(0.2 0.024 270);
  --ink: oklch(0.94 0.012 270);
  --muted: oklch(0.72 0.03 270);
  --line: oklch(0.3 0.03 270);
  --primary: oklch(0.62 0.155 270);
  --primary-fg: oklch(0.98 0.01 270);
  --accent: oklch(0.74 0.155 48);
  --danger: oklch(0.62 0.2 25);
  --focus: oklch(0.74 0.14 270);
  --bezel: oklch(0.08 0 0);
  --sans: "Public Sans", "Segoe UI", sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, monospace;
  --radius: 10px;
  --z-float: 4;
  --z-popup: 8;
  --space: 12px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.45;
  text-rendering: optimizeLegibility;
}

button,
input,
select {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: 1.15rem;
  font-weight: 650;
  letter-spacing: -0.02em;
  text-wrap: balance;
}

h2 {
  font-size: 0.95rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  text-wrap: balance;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.skip {
  position: absolute;
  left: 12px;
  top: -40px;
  z-index: 20;
  background: var(--primary);
  color: var(--primary-fg);
  padding: 8px 12px;
  border-radius: 8px;
}

.skip:focus {
  top: 12px;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.app {
  height: 100%;
  display: grid;
  grid-template-rows: auto 1fr auto;
  min-height: 0;
}

.mast {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.mast-title {
  min-width: 0;
}

.live {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 12px;
  margin-top: 2px;
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: oklch(0.72 0.16 155);
  box-shadow: 0 0 0 3px oklch(0.72 0.16 155 / 0.18);
}

.dot.is-spin {
  background: var(--accent);
}

.mast-stats {
  display: flex;
  gap: 18px;
  flex: 1;
  min-width: 0;
}

.stat-label {
  display: block;
  color: var(--muted);
  font-size: 11px;
}

.stat-value {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--mono);
  font-size: 15px;
  font-weight: 500;
}

.mast-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.stage {
  display: grid;
  grid-template-columns: minmax(300px, 360px) 1fr;
  min-height: 0;
}

.rail {
  min-height: 0;
  overflow: auto;
  border-right: 1px solid var(--line);
  background: var(--surface);
  display: flex;
  flex-direction: column;
}

.rail-toggle,
.text-btn,
.ghost {
  background: transparent;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 6px 10px;
  color: var(--ink);
}

.rail-toggle {
  margin: 10px 12px 0;
  width: calc(100% - 24px);
}

.ghost:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.map-wrap {
  position: relative;
  min-height: 0;
  background: var(--bezel);
}

.map-root {
  position: absolute;
  inset: 0;
}

.map-float {
  position: absolute;
  z-index: var(--z-float);
  top: 12px;
  left: 12px;
  max-width: min(320px, calc(100% - 24px));
}

.legend,
.detail,
.banner,
.mini-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 12px;
}

.legend-head,
.list-head,
.timeline-head,
.detail-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.legend-title {
  font-weight: 650;
}

.legend-stops {
  list-style: none;
  margin: 10px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 6px 10px;
  font-size: 12px;
  color: var(--muted);
}

.legend-stops li,
.detail-color {
  display: flex;
  align-items: center;
  gap: 8px;
}

.swatch {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
  flex: 0 0 auto;
}

.legend-note,
.hint,
.list-more,
.empty {
  color: var(--muted);
  font-size: 12px;
