node <<'NODE'
const list = await fetch("http://127.0.0.1:9333/json/list").then(r => r.json());
const page = list.find(t => t.type === "page" && t.url.includes("9302"));
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0;
const pending = new Map();
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
  }
};
function send(method, params) {
  ws.send(JSON.stringify({ id: ++id, method, params }));
  return new Promise((resolve, reject) => pending.set(msgId(id), { resolve, reject }));
  function msgId(n) { return n; }
}
await send("Page.enable");
await send("Runtime.enable");
await send("Page.reload", { ignoreCache: true });
await new Promise(r => setTimeout(r, 6000));
const { result } = await send("Runtime.evaluate", {
  expression: `({
    h1: document.querySelector('h1')?.textContent,
    listVisible: !!document.querySelector('.quake-row'),
    listCount: document.querySelectorAll('.quake-row').length,
    hasCanvas: !!document.querySelector('canvas')
  })`,
