  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
  flex: 0 0 auto;
}

.legend-note,
.hint,
.list-more,
.empty {
  color: var(--muted);
  font-size: 12px;
}

.legend-note {
  margin-top: 8px;
}

.seg {
  display: inline-flex;
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
}

.seg.wrap {
  display: flex;
  flex-wrap: wrap;
}

.seg-btn,
.chip {
  background: transparent;
  border: 0;
  padding: 6px 10px;
  color: var(--muted);
}

.seg-btn + .seg-btn {
  border-left: 1px solid var(--line);
}

.seg-btn.is-on,
.chip.is-on {
  background: var(--primary);
  color: var(--primary-fg);
}

.chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip {
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 5px 10px;
}

.chip:disabled {
  opacity: 0.55;
}

.controls {
  padding: 10px 12px;
  display: grid;
  gap: 10px;
  border-bottom: 1px solid var(--line);
