  font-weight: 650;
  letter-spacing: -0.015em;
  text-wrap: balance;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}

.skip {
  position: absolute;
  left: 12px;
  top: -40px;
  z-index: 20;
  background: var(--primary);
  color: var(--primary-fg);
  padding: 8px 12px;
  border-radius: 8px;
}

.skip:focus {
  top: 12px;
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.app {
  height: 100%;
  display: grid;
  grid-template-rows: auto 1fr auto;
  min-height: 0;
}

.mast {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.mast-title {
  min-width: 0;
}

.live {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 12px;
  margin-top: 2px;
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: oklch(0.72 0.16 155);
  box-shadow: 0 0 0 3px oklch(0.72 0.16 155 / 0.18);
}

.dot.is-spin {
  background: var(--accent);
}

.mast-stats {
  display: flex;
  gap: 18px;
  flex: 1;
  min-width: 0;
}

.stat-label {
  display: block;
  color: var(--muted);
  font-size: 11px;
}

.stat-value {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--mono);
  font-size: 15px;
  font-weight: 500;
}

.mast-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.stage {
  display: grid;
  grid-template-columns: minmax(300px, 360px) 1fr;
  min-height: 0;
}

.rail {
  min-height: 0;
  overflow: hidden;
  border-right: 1px solid var(--line);
  background: var(--surface);
  display: flex;
  flex-direction: column;
}

.rail-toggle,
.text-btn,
.ghost {
  background: transparent;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 6px 10px;
  color: var(--ink);
}

.rail-toggle {
  margin: 10px 12px 0;
  width: calc(100% - 24px);
}

.ghost:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.map-wrap {
  position: relative;
  min-height: 0;
  background: var(--bezel);
}

.map-root {
  position: absolute;
  inset: 0;
}

.map-float {
  position: absolute;
  z-index: var(--z-float);
  top: 12px;
  left: 12px;
  max-width: min(320px, calc(100% - 24px));
}

.map-detail {
  position: absolute;
  z-index: var(--z-float);
  top: 12px;
  right: 12px;
  width: min(340px, calc(100% - 24px));
  max-height: calc(100% - 24px);
  overflow: auto;
}

.map-detail .detail {
  margin: 0;
  max-height: none;
}

.legend,
.detail,
.banner,
.mini-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 12px;
}

.legend-head,
.list-head,
.timeline-head,
.detail-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.legend-title {
  font-weight: 650;
}

.legend-stops {
  list-style: none;
  margin: 10px 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 6px 10px;
  font-size: 12px;
  color: var(--muted);
}

.legend-stops li,
.detail-color {
  display: flex;
  align-items: center;
  gap: 8px;
}

.swatch {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
  flex: 0 0 auto;
}

.legend-note,
.hint,
.list-more,
.empty {
  color: var(--muted);
  font-size: 12px;
}

.legend-note {
  margin-top: 8px;
}

.seg {
  display: inline-flex;
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
}

.seg.wrap {
  display: flex;
  flex-wrap: wrap;
}

.seg-btn,
.chip {
  background: transparent;
  border: 0;
  padding: 6px 10px;
  color: var(--muted);
}

.seg-btn + .seg-btn {
  border-left: 1px solid var(--line);
}

.seg-btn.is-on,
.chip.is-on {
  background: var(--primary);
  color: var(--primary-fg);
}

.chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chip {
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 5px 10px;
}

.chip:disabled {
  opacity: 0.55;
}

.controls {
  padding: 10px 12px;
  display: grid;
  gap: 10px;
  border-bottom: 1px solid var(--line);
  overflow: auto;
  max-height: 46%;
  flex: 0 0 auto;
}

.field {
  display: grid;
  gap: 6px;
  border: 0;
  margin: 0;
  padding: 0;
}

.field legend,
.field-label {
  font-size: 12px;
  color: var(--muted);
  display: flex;
  justify-content: space-between;
}

.field-label strong {
  color: var(--ink);
  font-family: var(--mono);
  font-weight: 500;
}

input[type="search"] {
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 8px 10px;
}

input[type="range"] {
  width: 100%;
  accent-color: var(--primary);
}

.range-ends {
  display: flex;
  justify-content: space-between;
  color: var(--muted);
  font-size: 11px;
  font-family: var(--mono);
}

.checks {
  display: grid;
  gap: 8px;
}

.check {
  display: flex;
  align-items: center;
  gap: 8px;
}

.list-panel {
  padding: 12px;
  min-height: 0;
  flex: 1;
  overflow: auto;
}

.list-head {
  margin-bottom: 8px;
}

.sort select {
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 6px 8px;
}

.quake-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.quake-row {
  width: 100%;
  display: flex;
  gap: 10px;
  align-items: flex-start;
  text-align: left;
  background: transparent;
  border: 0;
  border-radius: 8px;
  padding: 8px;
}

.quake-row:hover {
  background: var(--surface-2);
}

.quake-row.is-selected {
  background: oklch(0.28 0.06 270);
}

.mag-pill,
.mag-hero {
  font-family: var(--mono);
  font-weight: 600;
  border-radius: 8px;
  flex: 0 0 auto;
}

.mag-pill {
  min-width: 46px;
  text-align: center;
  padding: 6px 0;
  font-size: 13px;
}

.quake-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.quake-place {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.offset {
  color: var(--muted);
}

.quake-meta {
  color: var(--muted);
  font-size: 12px;
}

.detail {
  margin: 10px 12px 0;
  overflow: auto;
  max-height: 42%;
  flex: 0 0 auto;
}

.detail-head {
  align-items: flex-start;
}

.detail-head h2 {
  font-size: 1rem;
}

.mag-hero {
  font-size: 1.35rem;
  padding: 8px 10px;
  min-width: 64px;
  text-align: center;
}

.detail-kicker {
  color: var(--muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.icon-btn {
  background: transparent;
  border: 1px solid var(--line);
  border-radius: 8px;
  width: 32px;
  height: 32px;
  font-size: 18px;
  line-height: 1;
}

.facts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 12px;
  margin: 12px 0;
}

.facts dt {
  color: var(--muted);
  font-size: 11px;
}

.facts dd {
  margin: 0;
  font-family: var(--mono);
  font-size: 12.5px;
}

.alert-red,
.alert-orange {
  color: var(--danger);
}

.alert-yellow {
  color: var(--accent);
}

.detail-color {
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 10px;
}

.usgs-link {
  color: var(--primary-fg);
  background: var(--primary);
  display: inline-block;
  text-decoration: none;
  padding: 8px 12px;
  border-radius: 8px;
  font-weight: 600;
}

.banner {
  margin: 12px;
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
}

.banner.overlay {
  position: absolute;
  z-index: var(--z-float);
  top: 12px;
  right: 12px;
}

.skeleton {
  padding: 12px;
  display: grid;
  gap: 8px;
}

.skel-row {
  height: 44px;
  border-radius: 8px;
  background: var(--surface-2);
}

.timeline {
  border-top: 1px solid var(--line);
  background: var(--surface);
  padding: 8px 16px 12px;
}

.timeline-track {
  position: relative;
  height: 44px;
  margin-top: 6px;
  color: var(--primary);
  touch-action: none;
}

.timeline-track svg {
  width: 100%;
  height: 100%;
  display: block;
}

.brush-dim {
  position: absolute;
  inset: 0 auto 0 0;
  background: oklch(0.1 0 0 / 0.45);
  pointer-events: none;
}

.brush-dim.right {
  left: auto;
  right: 0;
}

.brush {
  position: absolute;
  top: 0;
  bottom: 0;
  border: 1px solid var(--accent);
  background: oklch(0.74 0.155 48 / 0.12);
  pointer-events: none;
}

.mini-card {
  position: absolute;
  z-index: var(--z-float);
  left: 12px;
  right: 12px;
  bottom: 12px;
  display: flex;
  gap: 10px;
  align-items: center;
  text-align: left;
  color: inherit;
}

.maplibregl-popup.quake-tip .maplibregl-popup-content {
  background: var(--surface);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 6px 8px;
  box-shadow: none;
}

.maplibregl-popup.quake-tip .maplibregl-popup-tip {
  border-top-color: var(--surface);
}

.tip {
  display: flex;
  gap: 8px;
  align-items: baseline;
  max-width: 240px;
}

.tip-mag {
  font-family: var(--mono);
  font-weight: 600;
  color: var(--accent);
}

.tip-place {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.maplibregl-ctrl-attrib {
  font-size: 10px;
}

@media (max-width: 960px) {
  .mast {
    flex-wrap: wrap;
    gap: 10px;
  }

  .mast-stats {
    order: 3;
    width: 100%;
    justify-content: space-between;
  }

  .stage {
    grid-template-columns: 1fr;
  }

  .stage.is-map .rail,
  .stage.is-filters .map-wrap,
  .stage.is-list .map-wrap {
    display: none;
  }

  .stage.is-filters .rail,
  .stage.is-list .rail {
    border-right: 0;
    overflow: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}

