  border: 1px solid var(--line);
  border-radius: 8px;
  width: 32px;
  height: 32px;
  font-size: 18px;
  line-height: 1;
}

.facts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 12px;
  margin: 12px 0;
}

.facts dt {
  color: var(--muted);
  font-size: 11px;
}

.facts dd {
  margin: 0;
  font-family: var(--mono);
  font-size: 12.5px;
}

.alert-red,
.alert-orange {
  color: var(--danger);
}

.alert-yellow {
  color: var(--accent);
}

.detail-color {
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 10px;
}

.usgs-link {
  color: var(--primary-fg);
  background: var(--primary);
  display: inline-block;
  text-decoration: none;
  padding: 8px 12px;
  border-radius: 8px;
  font-weight: 600;
}

.banner {
  margin: 12px;
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: center;
}

.banner.overlay {
  position: absolute;
  z-index: var(--z-float);
  top: 12px;
  right: 12px;
}

.skeleton {
  padding: 12px;
  display: grid;
  gap: 8px;
}

.skel-row {
  height: 44px;
  border-radius: 8px;
  background: var(--surface-2);
}

.timeline {
  border-top: 1px solid var(--line);
  background: var(--surface);
  padding: 8px 16px 12px;
}

.timeline-track {
  position: relative;
  height: 44px;
  margin-top: 6px;
  color: var(--primary);
  touch-action: none;
}

.timeline-track svg {
  width: 100%;
  height: 100%;
  display: block;
}

.brush-dim {
  position: absolute;
  inset: 0 auto 0 0;
  background: oklch(0.1 0 0 / 0.45);
  pointer-events: none;
}

.brush-dim.right {
  left: auto;
  right: 0;
}

.brush {
  position: absolute;
  top: 0;
  bottom: 0;
  border: 1px solid var(--accent);
  background: oklch(0.74 0.155 48 / 0.12);
  pointer-events: none;
}

.mini-card {
  position: absolute;
  z-index: var(--z-float);
  left: 12px;
  right: 12px;
  bottom: 12px;
  display: flex;
  gap: 10px;
  align-items: center;
  text-align: left;
  color: inherit;
}

.maplibregl-popup.quake-tip .maplibregl-popup-content {
  background: var(--surface);
  color: var(--ink);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 6px 8px;
  box-shadow: none;
}

.maplibregl-popup.quake-tip .maplibregl-popup-tip {
  border-top-color: var(--surface);
}

.tip {
  display: flex;
  gap: 8px;
  align-items: baseline;
  max-width: 240px;
}

.tip-mag {
  font-family: var(--mono);
  font-weight: 600;
  color: var(--accent);
}

.tip-place {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.maplibregl-ctrl-attrib {
  font-size: 10px;
}

@media (max-width: 960px) {
  .mast {
    flex-wrap: wrap;
    gap: 10px;
  }

  .mast-stats {
    order: 3;
    width: 100%;
    justify-content: space-between;
  }

  .stage {
    grid-template-columns: 1fr;
  }

  .stage.is-map .rail,
  .stage.is-filters .map-wrap,
  .stage.is-list .map-wrap {
    display: none;
  }

  .stage.is-filters .rail,
  .stage.is-list .rail {
    border-right: 0;
    overflow: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
    animation: none !important;
  }
}

args.command:
node <<'NODE'
const list = await fetch("http://127.0.0.1:9333/json/list").then(r => r.json());
const page = list.find(t => t.type === "page" && t.url.includes("9302"));
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0;
const pending = new Map();
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
  }
};
function send(method, params) {
  ws.send(JSON.stringify({ id: ++id, method, params }));
  return new Promise((resolve, reject) => pending.set(id, { resolve, reject }));
}
await send("Page.enable");
await send("Runtime.enable");
await send("Page.reload", { ignoreCache: true });
await new Promise(r => setTimeout(r, 7000));
await send("Runtime.evaluate", {
  expression: `(() => {
    const rows = [...document.querySelectorAll('.quake-row')];
    const strong = rows.find(r => parseFloat(r.querySelector('.mag-pill')?.textContent || '0') >= 5) || rows[0];
    strong?.click();
    return true;
  })()`,
  returnByValue: true
});
await new Promise(r => setTimeout(r, 2500));
const { result } = await send("Runtime.evaluate", {
  expression: `({
    h1: document.querySelector('h1')?.textContent,
    list: document.querySelectorAll('.quake-row').length,
    detail: document.querySelector('.map-detail h2')?.textContent ?? document.querySelector('.detail h2')?.textContent,
    canvas: !!document.querySelector('canvas')
  })`,
  returnByValue: true
});
console.log(result.value);
const shot = await send("Page.captureScreenshot", { format: "png" });
const fs = await import("node:fs");
fs.writeFileSync("/tmp/earthquake-explorer.png", Buffer.from(shot.data, "base64"));
console.log("bytes", fs.statSync("/tmp/earthquake-explorer.png").size);
ws.close();
